import pandas as pd

def summarize_condition_model(data: dict, output_file: str = None) -> pd.DataFrame:
    """
    Build a table with one row per condition–model (e.g., "Role - GPT")
    and optionally save it to a CSV/Excel file.
    """
    rows = []

    for cond_model, countries in data.items():
        total_rows = 0
        error_count = 0
        neutral_count = 0

        for _country, topics in countries.items():
            for _topic_id, metrics in topics.items():
                total_rows += int(metrics.get("total_rows", 0))
                error_count += int(metrics.get("error_count", 0))
                neutral_count += int(
                    metrics.get("neutral_count", metrics.get("neutral", 0))
                )

        error_rate = (error_count / total_rows) if total_rows else 0.0
        neutrality_rate = (neutral_count / total_rows) if total_rows else 0.0

        rows.append(
            {
                "condition_model": cond_model,
                "error_rate": error_rate,
                "neutrality_rate": neutrality_rate,
                "error_count": error_count,
                "neutral_count": neutral_count,
                "total_rows": total_rows,
            }
        )

    df = pd.DataFrame(rows).set_index("condition_model").sort_index()

    # Save if a file path is provided
    if output_file:
        if output_file.endswith(".csv"):
            df.to_csv(output_file)
        elif output_file.endswith((".xlsx", ".xls")):
            df.to_excel(output_file)
        else:
            raise ValueError("Unsupported file format. Use .csv or .xlsx")

    return df


summary_df = summarize_condition_model(data, "results/agreement_ratio_plots/error_and_neutrality_table.csv")
print(summary_df)

